import {species,getSpecies} from './data.js?v=5';
import {sound,timeLabel} from './audio.js?v=5';
import {ResonanceField} from './resonance.js?v=5';
import {installShell,notify} from './ui.js?v=5';
import {readCollection,saveImpression} from './store.js?v=5';
import {exportPNG,exportSVG,patternSnapshot} from './export.js?v=5';
installShell();const $=s=>document.querySelector(s),field=new ResonanceField($('#studio-field'));
let sourceSpecies=null,job=0,lastMeters=0;
const controls=[['node-complexity','complexity','complexity-output',n=>n.toFixed(1)],['organic-distortion','distortion','distortion-output',n=>Math.round(n*100)+'%'],['particle-density','density','density-output',n=>Math.round(n*100)+'%'],['line-detail','detail','detail-output',n=>n.toFixed(1)],['audio-response','response','response-output',n=>n.toFixed(1)]];
for(const [id,key,out,format] of controls)$('#'+id).addEventListener('input',e=>{const n=+e.target.value;$('#'+out).textContent=format(n);field.setSettings({[key]:n})});
function syncControls(){for(const [id,key,out,format] of controls){$('#'+id).value=field[key];$('#'+out).textContent=format(field[key])}}
function selectColor(token){const color=getComputedStyle(document.documentElement).getPropertyValue(token).trim();field.setColor(color);document.querySelectorAll('[data-color]').forEach(b=>{const selected=b.dataset.color===token;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected)})}
document.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>selectColor(b.dataset.color)));
$('#reset-studio').addEventListener('click',()=>{field.phase=0;field.setSettings({complexity:4.5,distortion:.65,density:1,detail:1,response:1});selectColor('--accent');syncControls();notify('声纹参数已重置')});
async function loadDemo(id,autoplay=false,changeAppearance=true){const token=++job;try{const s=getSpecies(id);sourceSpecies=s;await sound.demo(s);if(token!==job)return;if(changeAppearance){field.setSettings({complexity:s.complexity});selectColor(s.color);syncControls()}if(autoplay)await sound.play()}catch(e){notify(e.message)}}
$('#demo-select').addEventListener('change',e=>{if(e.target.value)loadDemo(e.target.value)});
async function upload(file){const token=++job;if(!file)return;$('#track-name').textContent='正在分析声音…';try{await sound.upload(file);if(token!==job)return;sourceSpecies=null;$('#demo-select').value='';notify('音频已载入，点击播放即可驱动声纹')}catch(e){notify(e.message);updateTransport()}}
$('#audio-upload').addEventListener('change',e=>upload(e.target.files[0]));
const zone=$('#upload-zone');for(const type of ['dragenter','dragover'])zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('dragging')});for(const type of ['dragleave','drop'])zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('dragging')});zone.addEventListener('drop',e=>upload(e.dataTransfer.files[0]));
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()});
$('#lab-play').addEventListener('click',async()=>{try{if(sound.state==='playing'){sound.pause()}else{if(!sound.buffer&&sourceSpecies)await loadDemo(sourceSpecies.id,false,false);await sound.play()}}catch(e){notify(e.message)}});$('#lab-stop').addEventListener('click',()=>sound.stop());$('#lab-volume').addEventListener('input',e=>sound.setVolume(e.target.value));$('#lab-seek').addEventListener('input',e=>sound.seek(e.target.value));
function updateTransport(){if(sound.kind==='demo'&&sound.speciesId){sourceSpecies=getSpecies(sound.speciesId);$('#demo-select').value=sound.speciesId}const ready=!!sound.buffer,playing=sound.state==='playing';$('#lab-play').disabled=!ready;$('#lab-stop').disabled=!ready;$('#lab-seek').disabled=!ready;$('#lab-play').textContent=playing?'Ⅱ':'▶';$('#lab-play').setAttribute('aria-label',playing?'暂停音频':'播放音频');$('#track-name').textContent=sound.state==='loading'?'正在读取音频…':sound.name||'选择一段声音，或直接触碰画布';$('#track-source').textContent=sound.kind==='upload'?'本地音频 · 仅在浏览器内处理':sound.kind==='demo'?'合成演示 · 非真实动物录音':'所有声音均由你主动播放';$('#lab-seek').max=sound.duration||10;$('#lab-seek').value=sound.position;$('#lab-time').textContent=timeLabel(sound.position)+' / '+timeLabel(sound.duration);$('#render-state').textContent=({playing:'声音正在驱动形态',paused:'声音已暂停',ended:'聆听结束',loading:'正在读取音频',ready:'准备播放',empty:'等待声音'})[sound.state]||''}
sound.addEventListener('statechange',updateTransport);sound.addEventListener('progress',updateTransport);
sound.addEventListener('metrics',()=>{const m=sound.metrics;field.setAudio(m);if(performance.now()-lastMeters<110&&sound.state==='playing')return;lastMeters=performance.now();$('#metric-rms').textContent=m.rms.toFixed(3);$('#metric-centroid').textContent=Math.round(m.centroid)+' Hz';for(const key of ['low','mid','high']){$('#metric-'+key).textContent=Math.round(m[key]*100)+'%';$('#meter-'+key).style.transform=`scaleX(${Math.min(1,m[key])})`}$('#meter-rms').style.transform=`scaleX(${Math.min(1,m.rms*5)})`});
document.querySelectorAll('[data-export]').forEach(b=>b.addEventListener('click',()=>{try{const kind=b.dataset.export;if(kind==='svg')exportSVG(field);else exportPNG(field,kind==='transparent');notify('声纹已导出')}catch(e){notify('导出暂时失败，请重试。')}}));
$('#save-impression').addEventListener('click',()=>{try{saveImpression({name:sourceSpecies?.name||(sound.kind==='upload'?sound.name.replace(/\.[^.]+$/,''):'我的共振'),speciesId:sourceSpecies?.id||null,source:sound.kind==='upload'?'本地音频':sound.kind==='demo'?'合成声景演示':'触碰生成',settings:field.settings(),image:patternSnapshot(field),type:'pattern'});notify('已收藏，在「我的声音」里查看')}catch(e){notify(e.message)}});
$('#studio-field').addEventListener('dblclick',e=>field.pulse(e));
$('#fullscreen-canvas').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('.studio-canvas').requestFullscreen)await $('.studio-canvas').requestFullscreen();else notify('此浏览器暂不支持全屏，横屏可获得更大画布')}catch{notify('此浏览器暂不支持全屏')}});
$('#panel-toggle').addEventListener('click',()=>{const open=!$('.studio-panel').classList.contains('open');$('.studio-panel').classList.toggle('open',open);$('#panel-toggle').setAttribute('aria-expanded',open)});
const params=new URLSearchParams(location.search);const restored=readCollection().find(s=>s.id===params.get('impression'));
if(restored?.settings){const settings=restored.settings;field.phase=Number(settings.phase)||0;field.setSettings(settings);if(/^#[0-9a-f]{3,8}$/i.test(settings.color)){field.setColor(settings.color);document.querySelectorAll('[data-color]').forEach(b=>{const same=getComputedStyle(document.documentElement).getPropertyValue(b.dataset.color).trim().toLowerCase()===settings.color.toLowerCase();b.classList.toggle('selected',same);b.setAttribute('aria-pressed',same)})}syncControls();if(restored.speciesId){$('#demo-select').value=restored.speciesId;sourceSpecies=getSpecies(restored.speciesId)}notify('已恢复这张声音印记的参数')}
if(params.has('sound')&&species.some(s=>s.id===params.get('sound'))){$('#demo-select').value=params.get('sound');sourceSpecies=getSpecies(params.get('sound'));field.setSettings({complexity:sourceSpecies.complexity});selectColor(sourceSpecies.color);syncControls();$('#track-name').textContent=sourceSpecies.name+' · 点击播放载入演示';$('#lab-play').disabled=false;}
updateTransport();if(sourceSpecies&&!sound.buffer){$('#lab-play').disabled=false;$('#track-name').textContent=sourceSpecies.name+' · 点击播放载入演示';}

if(restored&&!sourceSpecies&&!sound.buffer)$('#track-name').textContent='声纹已恢复 · 重新上传声音以继续共振';
